/* ==UserStyle==
@name           Pplware, versão limpa [Dark Mode | Modo Escuro]
@namespace      USO Archive
@author         ZarkBit
@description    `Página do Pplware mais limpa e sem ads [Dark Mode | Modo Escudo]`
@version        20260401.1.0
@license        CC0-1.0
@preprocessor   default
==/UserStyle== */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("pplware.sapo.pt") {
/* === LAYOUT === */
    body {
        padding-top: 0;
    }
    #page {
        background-color: #01265D;
    }
    .content {
        border-right: none;
        width: 100%;
    }
    .content .post,
    .content .page {
        width: unset;
        padding: 11px 25px 10px 25px;
    }
    .col-2cl .main-inner {
        background: none;
        padding-right: 0;
        max-width: 80%;
        margin: auto;
    }
    /* === TAGS/CATEGORY NOTE === */
    .page-title.pad.group {
        padding: 10px 0px 10px 10px;
    }
    .page-title span {
        color: #6aadff;
    }
    .page-title i,
    .page-title h1 {
        color: #e8e8e8;
    }
    /* === HEADER === */
    .header-left,
    .header-right {
        max-height: 85px;
    }
    #header .pad {
        padding: 0;
    }
    /* === POST STYLES === */
    .single .post,
    .blog .post {
        box-shadow: 0 0 5px 1px rgba(0, 0, 0, 0.75);
        border-radius: 0;
        padding: 10px 15px;
    }
    .blog .post {
        padding: 11px 25px 10px 25px;
        max-width: none;
    }
    .entry.excerpt {
        padding: 11px 20px 10px 20px;
        color: #e8e8e8 !important;
    }
    .post-title {
        text-align: center;
    }
    /* === POST LIST === */
    @media only screen and (min-width: 720px) {
        .post-list .post-row {
            padding: 0;
            float: none;
            display: flex;
            justify-content: center;
            gap: 10px;
            width: unset;
            margin-right: 0 !important;
            box-sizing: border-box;
            align-items: stretch;
        }
        .post-list .post-row .invisible-mobile {
            width: 45%;
            box-sizing: border-box;
            display: flex;
            flex-direction: column;
        }
        .post-list .post-row .invisible-mobile .post {
            flex: 1;
        }
    }
    .post-list .post,
    .post-list .page {
        width: 100%;
        padding: 10px;
        box-sizing: border-box;
    }
    .post-list .post-inner {
        margin-right: 0;
    }
    /* === MARKETED ARTICLES === */
    /* Article list PUB */
    .post-byline span[style*="font-size: smaller"] {
        color: yellow !important;
    }

    /* Article page PUB */
    .single .post-byline > span:not(.comments-link) {
        color: yellow !important;
    }
    /* === E Porque Hoje é Sexta === */
    .box-shadow,
    .box-download,
    .galeria-numerada li a,
    .wpcmsdev-box,
    .wpcmsdev-box .box-title,
    .wpcmsdev-toggle {
        background: #2a3a4a !important;
    }
    /* === NOTEBOX === */
    .notebox,
    .page-title {
        background: #2a3a4a !important;
        color: #e8e8e8 !important;
        border-bottom: none;
    }
    /*=== INLINE STYLES === */
    div[style*="max-width: 720px"] {
        margin-left: auto !important;
        margin-right: auto !important;
    }
    div[style*="background-color: #f9f9f9"] a {
    color: #6aadff !important;
    border-color: #6aadff !important;
    }
    div[style*="background-color: #f2f2f2"],
    div[style*="background-color:#e6f0ff"],
    .entry .wp-caption {
        background: #2a3a4a !important;
    }
    div[style*="background: #fff"] p,
    div[style*="background: #fff"] li,
    .entry .wp-caption-text,
    div[style*="background: #f7f7f7"] p,
    div[style*="background-color: #f5f1e6"] p,
    div[style*="background-color: #f5f1e6"] li,
    div[style*="background-color: #eef6ff"] p,
    div[style*="background: #eef6ff"] li,
    div[style*="background: #f3fff4"] p,
    div[style*="background-color:#fff3cd"] p,
    div[style*="background-color:#fff3cd"] li,
    div[style*="background-color: #f9f9f9"] p {
        color: #e8e8e8 !important;
    }
    div[style*="background: #f7f7f7"],
    div[style*="background: #f8fafc"],
    div[style*="background: #f8fafc"] p,
    div[style*="background: #fff"],
    div[style*="background: #eef6ff"],
    .ppl-cta-box,
    div[style*="background-color: #f5f1e6"],
    div[style*="background-color: #eef6ff"],
    div[style*="background: #f3fff4"],
    div[style*="background-color:#fff3cd"],
    div[style*="background-color: #f9f9f9"] {
        background: #2a3a4a !important;
        color: #e8e8e8 !important;
    }
    /* === IMAGES === */
    .home .post-inner img[class*="wp-image-"],
    .archive .post-inner img[class*="wp-image-"] {
        width: 60%;
        margin-left: auto;
        margin-right: auto;
        display: block;
    }
    .article-box-img,
    .entry img.aligncenter,
    .entry img.alignnone {
        width: 55%;
        margin-left: auto;
        margin-right: auto;
        display: block;
    }
    .article-box-img {
        width: 75%;
    }
    /* === MISC === */
    .pad {
        padding: 10px 0 0 0;
    }
    .embed-container {
        box-shadow: 0 0 5px 1px rgba(0, 0, 0, 0.75);
    }
    .pdfemb-viewer {
        margin-left: auto !important;
        margin-right: auto !important;
    }
    /* === DARK MODE === */
    .main {
        background-color: #1a1a2e !important;
    }
    .post,
    .page {
        background-color: #1e2a3a;
        color: #e8e8e8;
    }
    .post a,
    .page a {
        color: #6aadff;
    }
    .post a:hover,
    .page a:hover {
        color: #9fcfff;
    }
    .post-byline,
    .post-byline a {
        color: #a0b4c8;
    }
    .entry p,
    .entry li {
        color: #e8e8e8 !important;
    }
    .post-title,
    .post-title a {
        color: #e8e8e8;
    }
    .post-title a:hover {
        color: #6aadff;
    }
    .content .post-title {
        color: #6aadff;
    }
    .entry-inner h1,
    .entry-inner h2,
    .entry-inner h3,
    .entry-inner h4,
    .entry-inner h5,
    .entry-inner h6 {
        color: #e8e8e8 !important;
    }
    .entry-inner p,
    .entry-inner li,
    .entry-inner td {
        color: #e8e8e8;
    }
    .entry-inner table tr,
    .entry-inner table tr.alt {
        background-color: #1e2a3a !important;
        color: #e8e8e8 !important;
    }

    .entry-inner table tr.alt {
        background-color: #2a3a4a !important;
    }

    .entry-inner table td {
        color: #e8e8e8 !important;
    }
    .wp_syntax table {
        max-width: 100%;
        display: block;
        overflow-x: auto;
        background-color: #2a3a4a !important;
    }
    .entry-inner code,
    .wp_syntax td.code,
    .entry-inner td.code,
    .entry-inner pre {
        background-color: #2a3a4a !important;
        color: #e8e8e8 !important;
    }
    [style*="color: #483d8b"] {
        color: #6b5bcf !important;
    }
    /* === COMMENTS === */
    .commentlist .comment-body {
        box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3),
        0 0 40px rgba(0, 0, 0, 0.1) inset;
        border-radius: 0;
        background: #1e2a3a !important;
        padding: 10px 10px 10px 15px;
        color: #e8e8e8 !important;
    }
    .commentlist .comment-body a {
        color: #6aadff;
    }
    .commentlist .fn {
        color: #e8e8e8 !important;
    }
    .commentlist .comment-body p {
        color: #e8e8e8;
    }
    .entry blockquote p {
        color: #b9b9b9 !important;
    }
    /* === COMMENT BOX === */
    .comment-form {
        background-color: #1e2a3a !important;
        color: #e8e8e8;
    }
    .comment-respond .comment-form label,
    #respond label,
    #reply-title {
        color: #a0b4c8;
    }
    #respond input,
    #respond textarea {
        background-color: #2a3a4a;
        color: #e8e8e8;
        border: 1px solid #4a6a8a;
    }
    #respond input[type="submit"] {
        background-color: #2e78cc;
        color: #e8e8e8;
        border: none;
        cursor: pointer;
    }
    #respond input[type="submit"]:hover {
        background-color: #4a9aee;
    }
    /* === AD BLOCKING & CLEANUP === */
    .google_news,
    .parceiro_iframe,
    #LeaderboardPos1,
    #LeaderboardPos2,
    #LeaderboardPos3,
    #LeaderboardPos4,
    #LeaderboardPos5,
    #bsu-placeholder,
    #bsu-v2-ctn,
    .header-pub-sapo,
    #top-pub,
    .ban-horizontal-artigo,
    .full-share-box,
    .post-tags,
    .pad.group hr,
    .ppl_lost_posts,
    .col-2cl .s1,
    #footer,
    ul.post-nav.group,
    h4.heading,
    ul.related-posts.group,
    #disclaimer,
    #ebAd60569025_billboard_div_0_60569025_2965759004516435,
    #\#sidepub,
    #taboola-below-article-thumbnails,
    .ob-smartfeed-wrapper,
    .OUTBRAIN,
    [data-widget-id*="AR_"],
    [data-widget-id*="FMS_CP_"],
    .ob-widget,
    .ob-feed-layout,
    [id*="FlooradPos"],
    [data-pub-formatid="Floorad"],
    div[data-pub="appNexus"] {
        display: none !important;
    }
}
